{"explanation":"A radian measures an angle by comparing the length of its circular arc to the circle’s radius: θ = arc length ÷ radius. One radian is the angle that cuts off an arc exactly as long as the radius—about 57.3°. Drag the yellow point to see the arc length and angle grow together; a full turn is 2π radians.","manimCode":"const center = [-2.5, 0, 0];
const radius = 2;
let theta = 1;
const pointAt = a => [center[0] + radius * Math.cos(a), center[1] + radius * Math.sin(a), 0];

const title = new Text({ text: 'A radian: an angle measured by an arc', fontSize: 30, color: WHITE });
title.moveTo([0, 3.15, 0]);
const circle = new Circle({ radius, color: GRAY });
circle.moveTo(center);
circle.setStrokeWidth(2);
const baseRadius = new Line({ start: center, end: pointAt(0), color: BLUE });
baseRadius.setStrokeWidth(4);
const movingRadius = new Line({ start: center, end: pointAt(theta), color: BLUE });
movingRadius.setStrokeWidth(4);
const originDot = new Dot({ point: center, radius: 0.05, color: WHITE });
const handle = new Dot({ point: pointAt(theta), radius: 0.14, color: YELLOW });

const arcSegments = [];
const segmentCount = 80;
for (let i = 0; i < segmentCount; i++) {
  const segment = new Line({ start: pointAt(theta * i / segmentCount), end: pointAt(theta * (i + 1) / segmentCount), color: YELLOW });
  segment.setStrokeWidth(6);
  arcSegments.push(segment);
}
const arcGroup = new VGroup(...arcSegments);
const radiusLabel = new Text({ text: 'radius r = 2', fontSize: 22, color: BLUE });
radiusLabel.moveTo([-1.5, -0.35, 0]);
const arcLabel = new Text({ text: 'arc length s', fontSize: 22, color: YELLOW });
arcLabel.moveTo([-2.5, 2.4, 0]);

const formula = new MathTex({ latex: '\\theta = \\frac{s}{r}', color: WHITE });
await formula.waitForRender();
formula.moveTo([3.1, 1.95, 0]);
const arcReadout = new Text({ text: '', fontSize: 26, color: YELLOW });
arcReadout.moveTo([3.1, 0.95, 0]);
const angleReadout = new Text({ text: '', fontSize: 28, color: WHITE });
angleReadout.moveTo([3.1, 0.25, 0]);
const degreesReadout = new Text({ text: '', fontSize: 22, color: GRAY });
degreesReadout.moveTo([3.1, -0.35, 0]);
const insight = new Text({ text: '', fontSize: 22, color: GREEN });
insight.moveTo([3.1, -1.05, 0]);
const resetButton = new Rectangle({ width: 2.8, height: 0.55, color: GREEN });
resetButton.setFill(GREEN, 0.15);
resetButton.moveTo([3.1, -2.05, 0]);
const resetLabel = new Text({ text: 'Show 1 radian', fontSize: 22, color: GREEN });
resetLabel.moveTo([3.1, -2.05, 0]);
const hint = new Text({ text: 'Drag the yellow point around the circle', fontSize: 23, color: GRAY });
hint.moveTo([0, -3.15, 0]);

function update() {
  handle.moveTo(pointAt(theta));
  movingRadius.setEnd(pointAt(theta));
  for (let i = 0; i < segmentCount; i++) {
    arcSegments[i].setStart(pointAt(theta * i / segmentCount));
    arcSegments[i].setEnd(pointAt(theta * (i + 1) / segmentCount));
  }
  arcReadout.setText('s = ' + (radius * theta).toFixed(2));
  angleReadout.setText('Angle = ' + theta.toFixed(2) + ' rad');
  degreesReadout.setText('About ' + (theta * 180 / Math.PI).toFixed(1) + ' degrees');
  insight.setText(Math.abs(theta - 1) < 0.025 ? 'Arc = radius: one radian!' : 'Arc = ' + theta.toFixed(2) + ' radii');
}
update();
scene.add(title, formula, radiusLabel, arcLabel, arcReadout, angleReadout, degreesReadout, insight, resetButton, resetLabel, hint);
await scene.play(new Create(circle));
await scene.play(new AnimationGroup([new Create(baseRadius), new Create(movingRadius), new FadeIn(arcGroup), new FadeIn(originDot), new FadeIn(handle)]));

makeDraggable(handle, scene, { onDrag: (mob, pos) => {
  const dx = pos[0] - center[0];
  const dy = pos[1] - center[1];
  if (Math.hypot(dx, dy) < 0.15) { update(); return; }
  let angle = Math.atan2(dy, dx);
  if (angle < 0) angle += 2 * Math.PI;
  theta = Math.max(0.01, Math.min(2 * Math.PI - 0.01, angle));
  update();
} });
const resetToOne = () => { theta = 1; update(); };
makeClickable(resetButton, scene, { onClick: resetToOne });
makeClickable(resetLabel, scene, { onClick: resetToOne });
await scene.wait(999999);"}

